CREATE TABLE profiles (id INT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, headline VARCHAR(150) NOT NULL, bio TEXT NOT NULL, email VARCHAR(150) NOT NULL, github_url VARCHAR(500) NOT NULL);
CREATE TABLE projects (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,stack VARCHAR(200) NOT NULL,link VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE skills (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,level VARCHAR(80) NOT NULL);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(250) NOT NULL);
CREATE TABLE sessions (sid VARCHAR(128) PRIMARY KEY,data MEDIUMTEXT NOT NULL,expires_at DATETIME NOT NULL,INDEX(expires_at));
